"""Opt-in UI testing support generated by the FastAPI project scaffold."""

from __future__ import annotations

import tomllib
from pathlib import Path

import pytest

from hedron.cli import main
from hedron.cli.discovery import scaffold_dep


def test_with_ui_tests_is_explicit_and_generates_a_working_test_project(
    tmp_path: Path, capsys: pytest.CaptureFixture[str]
) -> None:
    destination = tmp_path / "demo"
    with pytest.raises(SystemExit) as result:
        main(["new", "demo", "--path", str(destination), "--with-ui-tests"])
    assert result.value.code == 0
    output = capsys.readouterr().out

    project = tomllib.loads((destination / "pyproject.toml").read_text(encoding="utf-8"))
    assert project["dependency-groups"]["test"] == [scaffold_dep("hedron[testing]")]
    assert (destination / "tests" / "conftest.py").read_text(encoding="utf-8") == (
        'pytest_plugins = ["hedron.testing.pytest_plugin"]\n'
    )
    test_source = (destination / "tests" / "test_ui.py").read_text(encoding="utf-8")
    assert "from hedron.testing.browser_scenario import BrowserScenarioFactory" in test_source
    assert "ui.page.goto(ui.url)" in test_source
    assert "create_test_app" in (destination / "app.py").read_text(encoding="utf-8")
    assert (destination / "tests" / "README.md").is_file()
    assert '"tests/test_ui.py"' in output
    assert '"tests/README.md"' in output


def test_ui_tests_do_not_change_the_default_scaffold(
    tmp_path: Path, capsys: pytest.CaptureFixture[str]
) -> None:
    destination = tmp_path / "demo"
    with pytest.raises(SystemExit) as result:
        main(["new", "demo", "--path", str(destination)])
    assert result.value.code == 0
    _ = capsys.readouterr()
    project = tomllib.loads((destination / "pyproject.toml").read_text(encoding="utf-8"))
    assert "dependency-groups" not in project
    assert not (destination / "tests").exists()
    assert "create_test_app" not in (destination / "app.py").read_text(encoding="utf-8")


@pytest.mark.parametrize(
    "args",
    [
        ("new", "demo", "--flask"),
        ("new", "demo", "--django"),
        ("new", "element", "card"),
    ],
)
def test_ui_tests_reject_non_fastapi_scaffolds(
    tmp_path: Path,
    capsys: pytest.CaptureFixture[str],
    args: tuple[str, ...],
) -> None:
    destination = tmp_path / "demo"
    command = [*args, "--path", str(destination), "--with-ui-tests"]
    with pytest.raises(SystemExit) as result:
        main(command)
    assert result.value.code == 2
    assert "--with-ui-tests is only supported for FastAPI applications" in capsys.readouterr().err
    assert not (destination / "app.py").exists()


def test_ui_tests_reject_non_minimal_fastapi_template(
    tmp_path: Path, capsys: pytest.CaptureFixture[str]
) -> None:
    destination = tmp_path / "demo"
    with pytest.raises(SystemExit) as result:
        main(
            [
                "new",
                "demo",
                "--path",
                str(destination),
                "--template",
                "crud",
                "--with-ui-tests",
            ]
        )
    assert result.value.code == 2
    assert "only by the minimal FastAPI template" in capsys.readouterr().err
    assert not (destination / "app.py").exists()
